(()=>{"use strict";const $=id=>document.getElementById(id),I=window.CMI18n,locale=I?.formatLocale||"en-US",money=n=>I?I.currency(n,"USD",{maximumFractionDigits:2,minimumFractionDigits:2}):new Intl.NumberFormat(locale,{style:"currency",currency:"USD"}).format(n),num=n=>new Intl.NumberFormat(locale,{maximumFractionDigits:6}).format(n),numeric=id=>$(id).value.trim()===""?NaN:Number($(id).value),duration=years=>new Intl.NumberFormat(locale,{style:"unit",unit:"year",unitDisplay:"long",maximumFractionDigits:6}).format(years);function invalid(){for(const id of["result","chipInt","chipMult"])$(id).textContent="\u2014";$("yearRows").innerHTML="",$("verdict").className="verdict warn",$("verdictText").textContent="Enter finite nonnegative principal, rate and years, and a positive whole number of compounding periods. Results must fit the supported numeric range."}function render(){const[pv,rate,years,n]=["pv","rate","years","n"].map(numeric);if(![pv,rate,years,n].every(Number.isFinite)||Math.min(pv,rate,years)<0||!Number.isSafeInteger(n)||n<1)return invalid();const growth=t=>n*t*Math.log1p(rate/100/n),exponent=growth(years),factor=Math.exp(exponent),future=pv*factor,earned=pv*Math.expm1(exponent);if(![exponent,factor,future,earned].every(Number.isFinite))return invalid();$("result").textContent=money(future),$("chipInt").textContent=money(earned),$("chipMult").textContent=num(factor)+"\xD7";const dates=[...new Set([1,5,10,20,30,years].filter(y=>y<=years))].sort((a,b)=>a-b);$("yearRows").innerHTML=dates.map(y=>{const e=growth(y),value=pv*Math.exp(e),interest=pv*Math.expm1(e);return"<tr><td>"+duration(y)+'</td><td class="num">'+money(value)+'</td><td class="num">'+money(interest)+"</td></tr>"}).join(""),$("verdict").className="verdict",$("verdictText").textContent=I?.message("The modeled future value is {0}, with {1} interest over {2}. Every table row uses the entered compounding frequency.|\u6A21\u578B\u672A\u6765\u503C\u4E3A {0}\uFF0C\u5728 {2} \u5185\u7684\u5229\u606F\u4E3A {1}\u3002\u8868\u683C\u6BCF\u4E00\u884C\u5747\u91C7\u7528\u6240\u586B\u590D\u5229\u9891\u7387\u3002",[money(future),money(earned),duration(years)])||"The modeled future value is "+money(future)+", with "+money(earned)+" interest over "+duration(years)+". Every table row uses the entered compounding frequency."}document.querySelectorAll("input").forEach(e=>e.addEventListener("input",render)),render()})();
